function ensureFontDisplay(css:string):string{return css.replace(/@font-face\s*\{([\s\S]*?)\}/gi,(all,body:string)=>/\bfont-display\s*:/i.test(body)?all:`@font-face {${body.trimEnd()}\n  font-display: swap;\n}`);}
