function one(html:string,re:RegExp,replacement:string,label:string):string{const matches=html.match(new RegExp(re.source,re.flags.includes('g')?re.flags:`${re.flags}g`))??[];assert(matches.length===1,`${label}: expected exactly one match, found ${matches.length}`);return html.replace(re,replacement);}
async function roboto(html:string):Promise<string>{const re=/<link\b(?=[^>]*\bhref=["'](https:\/\/fonts\.googleapis\.com\/css\?family=Roboto:[^"']+)["'])(?=[^>]*\brel=["']stylesheet["'])[^>]*>/i,m=re.exec(html);assert(m?.[1],'Roboto stylesheet was not found');const escaped=m[1],url=escaped.replaceAll('&amp;','&');let replacement='';try{const response=await fetch(url,{headers:{'user-agent':'Mozilla/5.0'},signal:AbortSignal.timeout(6000)});assert(response.ok,`Roboto HTTP ${response.status}`);replacement=`<style id="sc-roboto-font-css">${ensureFontDisplay(await response.text())}</style>`;}catch{replacement=`<link rel="stylesheet" href="${escaped}" media="print" onload="this.media='all'">`;}return html.slice(0,m.index)+replacement+html.slice(m.index+m[0].length);}
function deferScripts(html:string,sha:string):string{for(const p of ['js/jquery-2.1.0.min.js','_pages/legacy.js','_js_dev/main-legacy.js','override/main.js','_pages/shop.js']){const suffix=p.startsWith('js/jquery')?'':`\\?v=${escapeRegExp(sha)}`,re=new RegExp(`<script\\b(?=[^>]*\\bsrc=["']${escapeRegExp(p)}${suffix}["'])([^>]*)><\\/script>`,'i');let n=0;html=html.replace(re,(_all,attrs:string)=>{n++;return /\bdefer\b/i.test(attrs)?_all:`<script defer fetchpriority="low"${attrs}></script>`;});assert(n===1,`Expected one local runtime script for ${p}, found ${n}`);}return html;}
