function hardLazy(html:string):[string,number]{let seen=0;html=html.replace(/(<div\b[^>]*class=["'][^"']*\b(?:imgShop|imgLiquidNoFillShop)\b[^"']*["'][^>]*>\s*<img\b)([^>]*)(>)/gi,(full,prefix:string,attrs:string,close:string)=>{seen++;if(seen<=4)return full;const src=/\s+src=["']([^"']+)["']/i.exec(attrs)?.[1];if(!src)return full;attrs=attrs.replace(/\s+src=["'][^"']+["']/i,'').replace(/\s+fetchpriority=["'][^"']+["']/gi,'')+` data-sc-src="${src}" fetchpriority="low"`;return `${prefix}${attrs}${close}`;});assert(seen>=100,`Expected the catalogue product images, found only ${seen}`);return [html,seen];}
