export async function optimizeDelivery():Promise<void>{const sha=githubSha(),file=path.join(SITE,'index.html'),legacy=path.join(SITE,'_pages/legacy.css'),override=path.join(SITE,'override/main.css');assert(fs.existsSync(legacy)&&fs.existsSync(override),'Bundled local stylesheets are missing');let html=read(file);const critical=`<style id="sc-pages-critical-css">\n${ensureFontDisplay(rebaseCss(read(legacy),'_pages/legacy.css')).trimEnd()}\n${ensureFontDisplay(rebaseCss(read(override),'override/main.css')).trimEnd()}\n</style>`;html=one(html,new RegExp(`<link\\b(?=[^>]*\\brel=["']stylesheet["'])(?=[^>]*\\bhref=["']_pages/legacy\\.css\\?v=${escapeRegExp(sha)}["'])[^>]*>`,'i'),critical,'legacy stylesheet');html=one(html,new RegExp(`<link\\b(?=[^>]*\\brel=["']stylesheet["'])(?=[^>]*\\bhref=["']override/main\\.css\\?v=${escapeRegExp(sha)}["'])[^>]*>\\s*`,'i'),'','override stylesheet');for(const a of ['_js_dev/main-legacy.js','override/main.js','override/main.css'])html=html.replace(new RegExp(`<link\\b(?=[^>]*\\brel=["']preload["'])(?=[^>]*\\bhref=["']${escapeRegExp(a)}\\?v=${escapeRegExp(sha)}["'])[^>]*>\\s*`,'i'),'');html=html.replace(/<link\b(?=[^>]*\brel=["']preconnect["'])(?=[^>]*\bhref=["']https:\/\/cdn\.jsdelivr\.net\/?["'])[^>]*>\s*/i,'');html=await roboto(html);html=deferScripts(html,sha);html=wrapHandlers(html);html=one(html,/<script\b(?=[^>]*\bsrc=["']https:\/\/www\.google\.com\/recaptcha\/api\.js["'])[^>]*>\s*<\/script>\s*/i,'','reCAPTCHA bootstrap');html=one(html,/<script>\s*\(function\(w,d,s,l,i\)[\s\S]*?GTM-WQPLGX9[\s\S]*?<\/script>\s*/i,'','GTM bootstrap');let productCount;[html,productCount]=hardLazy(html);const icon=/<img\b(?=[^>]*\bsrc=["']https:\/\/www\.sushiclub\.com\.ar\/iconos\/icons8-tiktok-32\.png["'])([^>]*)>/i.exec(html);if(icon&&icon.index!==undefined){let attrs=icon[1]??'';if(!/\bwidth=/i.test(attrs))attrs+=' width="22"';if(!/\bheight=/i.test(attrs))attrs+=' height="22"';html=html.slice(0,icon.index)+`<img${attrs}>`+html.slice(icon.index+icon[0].length);}html=loader(html);for(const rel of ['_pages/legacy.js','_pages/shop.js','_js_dev/main-legacy.js','override/main.js']){const p=path.join(SITE,rel);write(p,read(p).replace(/^\s*\/\/[@#]\s*sourceMappingURL=.*$/gm,'').replace(/\/\*# sourceMappingURL=[\s\S]*?\*\//g,''));}assert(html.includes('id="sc-pages-critical-css"'),'Critical local CSS was not inlined');assert(html.includes('w.dataLayer=w.dataLayer||[]'),'Deferred analytics queue bootstrap is missing');assert(html.split('data-sc-src=').length-1>=productCount-6,'Explicit product-image lazy loading was not applied');write(file,html);}
